proof:
:= by
      convert Fintype.linearIndependent_iff.mpr _;
      exact Fin.fintype n;
      intro g hg i;
      rw [ Fintype.linearIndependent_iff ] at hli;
      exact hli g ( by ext j; simpa using congr_fun hg ( Fin.castAdd N₂ j ) ) i

