    have h_fourier_coeff_bound : ‖(((2 * π : ℝ) ^ n : ℝ)⁻¹ * riemannK n u M m - fourierCoeffDistrib u m)‖ ≤ 2 * ∑' k : Fin n → ℤ, ‖fourierCoeffDistrib u k‖ := by
      have h_fourier_coeff_bound : ‖(((2 * π : ℝ) ^ n : ℝ)⁻¹ * riemannK n u M m)‖ ≤ ∑' k : Fin n → ℤ, ‖fourierCoeffDistrib u k‖ := by
        convert norm_riemannK_normalized_le hn hs hu M m using 1;
        norm_num;
      have h_fourier_coeff_bound : ‖fourierCoeffDistrib u m‖ ≤ ∑' k : Fin n → ℤ, ‖fourierCoeffDistrib u k‖ := by
        have h_fourier_coeff_bound : Summable (fun k : Fin n → ℤ => ‖fourierCoeffDistrib u k‖) := by
          convert summable_norm_of_memSobolev hn hs hu using 1;
        exact Summable.le_tsum h_fourier_coeff_bound m ( fun _ _ => norm_nonneg _ );
      exact le_trans ( norm_sub_le _ _ ) ( by linarith );
    rw [ h_fourier_coeff, norm_mul ];
    rw [ mul_pow, mul_assoc ];
    exact mul_le_mul_of_nonneg_left ( by nlinarith only [ show 0 ≤ ‖ftRn n φ fun j => ( m j : ℝ )‖ ^ 2 by positivity, show 0 ≤ ‖↑ ( ( 2 * Real.pi ) ^ n ) ⁻¹ * riemannK n u M m - fourierCoeffDistrib u m‖ ^ 2 by positivity, h_fourier_coeff_bound, show ‖↑ ( ( 2 * Real.pi ) ^ n ) ⁻¹ * riemannK n u M m - fourierCoeffDistrib u m‖ ^ 2 ≤ ( 2 * ∑' k : Fin n → ℤ, ‖fourierCoeffDistrib u k‖ ) ^ 2 by gcongr ] ) ( weight_nonneg s m );
  have h_dom : Summable (fun m : Fin n → ℤ => weight n s m * (2 * ∑' k : Fin n → ℤ, ‖fourierCoeffDistrib u k‖) ^ 2 * ‖ftRn n φ (fun j => (m j : ℝ))‖ ^ 2) := by
    convert hφ_rd s |> Summable.mul_left ( ( 2 * ∑' k : Fin n → ℤ, ‖fourierCoeffDistrib u k‖ ) ^ 2 ) using 2 <;> first | rfl | ring;
  have h_ab : ∀ m : Fin n → ℤ, Filter.Tendsto (fun M : ℕ => weight n s m * ‖fourierCoeffDistrib (riemannSumDistrib n φ u M - convDistrib n φ u) m‖ ^ 2) Filter.atTop (nhds 0) :=
    fun m => by simpa using Filter.Tendsto.const_mul _ ( ‹∀ m : Fin n → ℤ, Filter.Tendsto ( fun M : ℕ => ‖fourierCoeffDistrib ( riemannSumDistrib n φ u M - convDistrib n φ u ) m‖ ^ 2 ) Filter.atTop ( nhds 0 ) › m )
  have h_bound : ∀ᶠ M in Filter.atTop, ∀ m : Fin n → ℤ, ‖weight n s m * ‖fourierCoeffDistrib (riemannSumDistrib n φ u M - convDistrib n φ u) m‖ ^ 2‖ ≤ weight n s m * (2 * ∑' k : Fin n → ℤ, ‖fourierCoeffDistrib u k‖) ^ 2 * ‖ftRn n φ (fun j => (m j : ℝ))‖ ^ 2 := by
    filter_upwards [ Filter.eventually_gt_atTop 0 ] with M hM using fun m => by rw [ Real.norm_of_nonneg ( mul_nonneg ( weight_nonneg _ _ ) ( sq_nonneg _ ) ) ] ; exact ‹∀ M : ℕ, ∀ m : Fin n → ℤ, weight n s m * ‖fourierCoeffDistrib ( riemannSumDistrib n φ u M - convDistrib n φ u ) m‖ ^ 2 ≤ weight n s m * ( 2 * ∑' k : Fin n → ℤ, ‖fourierCoeffDistrib u k‖ ) ^ 2 * ‖ftRn n φ fun j => ↑ ( m j )‖ ^ 2› M m
  convert tendsto_tsum_of_dominated_convergence
      (f := fun M m => weight n s m *
        ‖fourierCoeffDistrib (riemannSumDistrib n φ u M - convDistrib n φ u) m‖ ^ 2)
      (g := fun _ => (0:ℝ))
      (bound := fun m => weight n s m * (2 * ∑' k : Fin n → ℤ, ‖fourierCoeffDistrib u k‖) ^ 2 * ‖ftRn n φ (fun j => (m j : ℝ))‖ ^ 2)
      h_dom h_ab h_bound using 1
  all_goals first
  | rfl
  | (simp only [ tsum_zero ])

:= by

  obtain ⟨b, hb⟩ : ∃ b : ((Fin n) → ℝ) → ℝ,
    (ContDiff ℝ ∞ b) ∧
    HasCompactSupport b ∧
    (∀ x, 0 ≤ b x) ∧
    (∫ x, b x) > 0 ∧
    (∀ x, b x ≠ 0 → (∀ j, |x j| < Real.pi)) := by

      obtain ⟨b, hb⟩ : ∃ b : ContDiffBump (0 : (Fin n) → ℝ), b.rOut < Real.pi := by
        refine' ⟨ _, _ ⟩;
        constructor;
        exact one_half_pos;
        exact show ( 1 / 2 : ℝ ) < 1 by norm_num;
        linarith [ Real.pi_gt_three ];
      refine' ⟨ fun x => b x, _, _, _, _, _ ⟩;
      · exact ContDiffBump.contDiff b;
      · exact b.hasCompactSupport;
      · exact fun x => ContDiffBump.nonneg b;
      · exact ContDiffBump.integral_pos b;
      · intro x hx j;
        have := b.support_eq;
        exact lt_of_le_of_lt ( by simpa using ( norm_le_pi_norm x j ) ) ( lt_of_lt_of_le ( mem_ball_zero_iff.mp ( this.subset hx ) ) hb.le );
  refine' ⟨ fun x => b x / ( ∫ x, b x ), _, _, _, _, _, _ ⟩ <;> simp_all +decide [ MeasureTheory.integral_div ];
  · exact hb.1.div_const _;
  · rw [ hasCompactSupport_iff_eventuallyEq ] at *;
    filter_upwards [ hb.2.1 ] with x hx using by simp +decide [ hx, hb.2.2.2.1.ne' ] ;
  · exact MeasureTheory.Integrable.div_const ( by exact ( by contrapose! hb; simp_all +decide [ MeasureTheory.integral_undef ] ) ) _;
  · exact fun x => div_nonneg ( hb.2.2.1 x ) hb.2.2.2.1.le;
  · linarith

