lemma MemSobolevDistrib.sub {s : ℝ} {a b : TrigPolyDual n}
    (ha : MemSobolevDistrib n s a) (hb : MemSobolevDistrib n s b) :
    MemSobolevDistrib n s (a - b)

proof:
:= by
  refine' .of_nonneg_of_le ( fun m => _ ) ( fun m => _ ) ( Summable.add ha hb |> Summable.mul_left 2 );
  · exact mul_nonneg ( by exact Real.rpow_nonneg ( add_nonneg zero_le_one ( Finset.sum_nonneg fun _ _ => sq_nonneg _ ) ) _ ) ( sq_nonneg _ );
  · 
    have h_triangle : ‖fourierCoeffDistrib (a - b) m‖ ^ 2 ≤ 2 * (‖fourierCoeffDistrib a m‖ ^ 2 + ‖fourierCoeffDistrib b m‖ ^ 2) := by
      have h_bound : ‖fourierCoeffDistrib (a - b) m‖ ≤ ‖fourierCoeffDistrib a m‖ + ‖fourierCoeffDistrib b m‖ := by
        convert norm_sub_le ( fourierCoeffDistrib a m ) ( fourierCoeffDistrib b m ) using 2
        all_goals rfl
      exact le_trans ( pow_le_pow_left₀ ( norm_nonneg _ ) h_bound 2 ) ( by linarith [ sq_nonneg ( ‖fourierCoeffDistrib a m‖ - ‖fourierCoeffDistrib b m‖ ) ] );
    nlinarith [ show 0 ≤ weight n s m by exact le_of_lt ( weight_pos s m ) ]

:= by

  have h_expand : ∀ i, (m i : ℝ) ^ 2 ≤ 2 * (m i - j i) ^ 2 + 2 * (j i) ^ 2 := by
    exact fun i => by linarith [ sq_nonneg ( m i - 2 * j i : ℝ ) ] ;
  have := Finset.sum_le_sum fun i ( hi : i ∈ Finset.univ ) => h_expand i;

  norm_cast at *;
  norm_num [ Finset.sum_add_distrib, ← Finset.mul_sum _ _ _ ] at *;
  nlinarith [ show 0 ≤ ∑ i, ( m i - j i ) ^ 2 from Finset.sum_nonneg fun _ _ => sq_nonneg _, show 0 ≤ ∑ i, j i ^ 2 from Finset.sum_nonneg fun _ _ => sq_nonneg _ ]

:= by
  by_cases hs : 0 ≤ s <;> simp_all +decide [ weight ];
  · rw [ abs_of_nonneg hs ];
    rw [ ← Real.mul_rpow, ← Real.mul_rpow ] <;> try positivity;
    exact Real.rpow_le_rpow ( by exact add_nonneg zero_le_one <| Finset.sum_nonneg fun _ _ => sq_nonneg _ ) ( by exact_mod_cast weight_base_submul m j ) hs;
  · have h_submul : (1 + ∑ i, (m i : ℝ) ^ 2) ≥ (1 + ∑ i, ((m i : ℝ) - (j i : ℝ)) ^ 2)⁻¹ * (1 + ∑ i, (j i : ℝ) ^ 2) / 2 := by
      field_simp;
      have h_submul : (1 + ∑ i, (j i : ℝ) ^ 2) ≤ 2 * (1 + ∑ i, ((m i : ℝ) - (j i : ℝ)) ^ 2) * (1 + ∑ i, (m i : ℝ) ^ 2) := by
        have := weight_base_submul j m
        exact this.trans ( by rw [ show ( ∑ i : Fin n, ( j i - m i : ℝ ) ^ 2 ) = ∑ i : Fin n, ( m i - j i : ℝ ) ^ 2 by exact Finset.sum_congr rfl fun _ _ => by ring ] );
      linarith;
    refine' le_trans ( Real.rpow_le_rpow_of_nonpos _ h_submul hs.le ) _;
    · exact div_pos ( mul_pos ( inv_pos.mpr ( add_pos_of_pos_of_nonneg zero_lt_one ( Finset.sum_nonneg fun _ _ => sq_nonneg _ ) ) ) ( add_pos_of_pos_of_nonneg zero_lt_one ( Finset.sum_nonneg fun _ _ => sq_nonneg _ ) ) ) zero_lt_two;
    · rw [ Real.div_rpow ( by positivity ) ( by positivity ), Real.mul_rpow ( by positivity ) ( by positivity ), Real.inv_rpow ( by positivity ) ];
      rw [ abs_of_neg hs, Real.rpow_neg ( by positivity ), Real.rpow_neg ( by positivity ) ] ; ring_nf ; norm_num

:= by
  conv_rhs => rw [ ← Equiv.tsum_eq ( Equiv.subRight i ) ] ;
  rfl

:= by
  refine' .of_nonneg_of_le ( fun i => mul_nonneg ( hf_nn i ) ( hg_nn _ ) ) ( fun i => _ ) ( hf.mul_right ( Real.sqrt ( ∑' m, g m ^ 2 ) ) );
  exact mul_le_mul_of_nonneg_left ( Real.le_sqrt_of_sq_le ( Summable.le_tsum ( hg_sq ) ( m - i ) ( fun _ _ => sq_nonneg _ ) ) ) ( hf_nn i )

:= by
  have h_conv_abs_summable : ∀ m, Summable (fun i => f i * g (m - i)) := by
    intro m
    apply conv_abs_summable hf_nn hg_nn hf hg_sq m;
  have h_cauchy_schwarz : ∀ m, (∑' i, f i * g (m - i)) ^ 2 ≤ (∑' i, f i) * (∑' i, f i * g (m - i) ^ 2) := by
    intro m;
    have h_cauchy_schwarz : ∀ (u v : (Fin n → ℤ) → ℝ), (∀ i, 0 ≤ u i) → (∀ i, 0 ≤ v i) → Summable (fun i => u i) → Summable (fun i => u i * v i ^ 2) → (∑' i, u i * v i) ^ 2 ≤ (∑' i, u i) * (∑' i, u i * v i ^ 2) := by
      intros u v hu hv hu_sum hv_sum
      have h_cauchy_schwarz : ∀ (N : Finset (Fin n → ℤ)), (∑ i ∈ N, u i * v i) ^ 2 ≤ (∑ i ∈ N, u i) * (∑ i ∈ N, u i * v i ^ 2) := by
        intro N;
        have h_cauchy_schwarz : ∀ (u v : (Fin n → ℤ) → ℝ), (∀ i, 0 ≤ u i) → (∀ i, 0 ≤ v i) → (∑ i ∈ N, u i * v i) ^ 2 ≤ (∑ i ∈ N, u i) * (∑ i ∈ N, u i * v i ^ 2) := by
          intros u v hu hv
          have h_cauchy_schwarz : ∀ (i j : Fin n → ℤ), u i * v i * u j * v j ≤ (u i * u j * v i ^ 2 + u i * u j * v j ^ 2) / 2 := by
            exact fun i j => by nlinarith only [ sq_nonneg ( v i - v j ), mul_nonneg ( hu i ) ( hu j ), mul_nonneg ( hu i ) ( hv j ), mul_nonneg ( hv i ) ( hu j ), mul_nonneg ( hv i ) ( hv j ) ] ;
          have h_cauchy_schwarz : ∑ i ∈ N, ∑ j ∈ N, u i * v i * u j * v j ≤ ∑ i ∈ N, ∑ j ∈ N, (u i * u j * v i ^ 2 + u i * u j * v j ^ 2) / 2 := by
            exact Finset.sum_le_sum fun i hi => Finset.sum_le_sum fun j hj => h_cauchy_schwarz i j;
          convert h_cauchy_schwarz using 1 <;> norm_num [ Finset.sum_add_distrib, ← Finset.mul_sum _ _ _, ← Finset.sum_div ] ; ring;
          · simp +decide only [sq, Finset.mul_sum _ _ _, mul_comm, mul_left_comm];
          · simp +decide [ ← Finset.mul_sum _ _ _, ← Finset.sum_mul, mul_assoc, mul_comm, mul_left_comm, Finset.sum_add_distrib ] ; ring;
            simp +decide [ mul_assoc, Finset.mul_sum _ _ _ ] ; ring;
        exact h_cauchy_schwarz u v hu hv;
      have h_cauchy_schwarz : Filter.Tendsto (fun N : Finset (Fin n → ℤ) => (∑ i ∈ N, u i * v i) ^ 2) Filter.atTop (nhds ((∑' i, u i * v i) ^ 2)) := by
        refine' Filter.Tendsto.pow _ _;
        refine' Summable.hasSum _;
        have h_cauchy_schwarz : Summable (fun i => u i * v i) := by
          have h_cauchy_schwarz : ∀ i, u i * v i ≤ u i + u i * v i ^ 2 := by
            exact fun i => by nlinarith only [ hu i, hv i, sq_nonneg ( v i - 1 ) ] ;
          exact Summable.of_nonneg_of_le ( fun i => mul_nonneg ( hu i ) ( hv i ) ) h_cauchy_schwarz ( hu_sum.add hv_sum );
        exact h_cauchy_schwarz;
      exact le_of_tendsto_of_tendsto' h_cauchy_schwarz ( Filter.Tendsto.mul ( hu_sum.hasSum ) ( hv_sum.hasSum ) ) fun N => by aesop;
    apply h_cauchy_schwarz f (fun i => g (m - i)) hf_nn (fun i => hg_nn (m - i)) hf;
    refine' .of_nonneg_of_le ( fun i => mul_nonneg ( hf_nn i ) ( sq_nonneg _ ) ) ( fun i => mul_le_mul_of_nonneg_left ( show g ( m - i ) ^ 2 ≤ ∑' j, g j ^ 2 from _ ) ( hf_nn i ) ) ( hf.mul_right _ );
    exact Summable.le_tsum ( hg_sq ) ( m - i ) ( fun _ _ => sq_nonneg _ );
  have h_fubini : ∑' m, ∑' i, f i * g (m - i) ^ 2 = ∑' i, f i * ∑' m, g (m - i) ^ 2 := by
    rw [ Summable.tsum_comm ];
    · simp +decide only [← tsum_mul_left];
    · have h_fubini : Summable (fun p : (Fin n → ℤ) × (Fin n → ℤ) => f p.1 * g p.2 ^ 2) := by
        exact .of_norm <| by simpa using Summable.mul_norm ( hf.norm ) ( hg_sq.norm ) ;
      convert h_fubini.comp_injective ( show Function.Injective ( fun p : ( Fin n → ℤ ) × ( Fin n → ℤ ) => ( p.1, p.2 - p.1 ) ) from fun p q h => by aesop ) using 1
      funext p; simp [Function.uncurry, Function.comp]
  have h_translation_invariance : ∀ i, ∑' m, g (m - i) ^ 2 = ∑' m, g m ^ 2 := by
    exact fun i => Equiv.tsum_eq ( Equiv.subRight i ) fun m => g m ^ 2;
  simp_all +decide [ tsum_mul_right, tsum_mul_left ];
  refine' ⟨ _, _ ⟩;
  · refine' Summable.of_nonneg_of_le ( fun m => sq_nonneg _ ) ( fun m => h_cauchy_schwarz m ) _;
    refine' Summable.mul_left _ _;
    contrapose! h_fubini;
    rw [ tsum_eq_zero_of_not_summable h_fubini ] ; norm_num;
    constructor;
    · intro H;
      have h_zero : ∀ m, f m = 0 := by
        exact fun m => le_antisymm ( le_trans ( Summable.le_tsum ( hf ) m ( fun _ _ => hf_nn _ ) ) H.le ) ( hf_nn m );
      exact h_fubini <| by simpa [ h_zero ] using summable_zero;
    · intro H; simp_all +decide [ tsum_eq_zero_of_not_summable ] ;

      have h_g_zero : ∀ m, g m = 0 := by
        exact fun m => sq_eq_zero_iff.mp ( le_antisymm ( le_trans ( Summable.le_tsum ( hg_sq ) m ( fun _ _ => sq_nonneg _ ) ) H.le ) ( sq_nonneg _ ) );
      exact h_fubini <| by simpa [ h_g_zero ] using summable_zero;
  · refine' le_trans ( Summable.tsum_le_tsum h_cauchy_schwarz _ _ ) _;
    · refine' Summable.of_nonneg_of_le ( fun m => sq_nonneg _ ) ( fun m => h_cauchy_schwarz m ) _;
      refine' Summable.mul_left _ _;
      contrapose! h_fubini;
      rw [ tsum_eq_zero_of_not_summable h_fubini ] ; norm_num;
      constructor;
      · intro H;
        have h_zero : ∀ m, f m = 0 := by
          exact fun m => le_antisymm ( le_trans ( Summable.le_tsum ( hf ) m ( fun _ _ => hf_nn _ ) ) H.le ) ( hf_nn m );
        exact h_fubini <| by simpa [ h_zero ] using summable_zero;
      · intro H; simp_all +decide [ tsum_eq_zero_of_not_summable ] ;

        have h_g_zero : ∀ m, g m = 0 := by
          exact fun m => sq_eq_zero_iff.mp ( le_antisymm ( le_trans ( Summable.le_tsum ( hg_sq ) m ( fun _ _ => sq_nonneg _ ) ) H.le ) ( sq_nonneg _ ) );
        exact h_fubini <| by simpa [ h_g_zero ] using summable_zero;
    · refine' Summable.mul_left _ _;
      contrapose! h_fubini;
      rw [ tsum_eq_zero_of_not_summable h_fubini ] ; norm_num;
      constructor <;> intro h <;> simp_all +decide [ tsum_eq_zero_of_not_summable ];
      · 
        have h_f_zero : ∀ m, f m = 0 := by
          exact fun m => le_antisymm ( le_trans ( Summable.le_tsum ( hf ) m ( fun _ _ => hf_nn _ ) ) h.le ) ( hf_nn m );
        exact h_fubini <| by simpa [ h_f_zero ] using summable_zero;
      · 
        have h_g_zero : ∀ m, g m = 0 := by
          exact fun m => sq_eq_zero_iff.mp ( le_antisymm ( le_trans ( Summable.le_tsum ( hg_sq ) m ( fun _ _ => sq_nonneg _ ) ) h.le ) ( sq_nonneg _ ) );
        exact h_fubini <| by simpa [ h_g_zero ] using summable_zero;
    · rw [ tsum_mul_left, h_fubini, sq, mul_assoc ]

:= by
  have h_peetre : ∀ m : Fin n → ℤ, (weight n s m) * ‖∑' i, b i * a (m - i)‖ ^ 2 ≤ (2 ^ (|s| / 2 : ℝ)) ^ 2 * (∑' i, ‖b i‖ * (weight n (|s| / 2) i) * Real.sqrt (weight n s (m - i)) * ‖a (m - i)‖) ^ 2 := by
    intro m
    have h_peetre_step : Real.sqrt (weight n s m) * ‖∑' i, b i * a (m - i)‖ ≤ 2 ^ (|s| / 2 : ℝ) * ∑' i, ‖b i‖ * (weight n (|s| / 2) i) * Real.sqrt (weight n s (m - i)) * ‖a (m - i)‖ := by
      have h_peetre_step : ∀ i : Fin n → ℤ, Real.sqrt (weight n s m) * ‖b i * a (m - i)‖ ≤ 2 ^ (|s| / 2 : ℝ) * ‖b i‖ * (weight n (|s| / 2) i) * Real.sqrt (weight n s (m - i)) * ‖a (m - i)‖ := by
        intro i
        have h_peetre_step : Real.sqrt (weight n s m) ≤ 2 ^ (|s| / 2 : ℝ) * weight n (|s| / 2) i * Real.sqrt (weight n s (m - i)) := by
          have h_peetre : weight n s m ≤ (2 : ℝ) ^ (|s|) * weight n (|s|) i * weight n s (m - i) := by
            convert peetre_weight s m ( m - i ) using 1 ; ring;
          convert Real.sqrt_le_sqrt h_peetre using 1;
          rw [ show ( 2 : ℝ ) ^ |s| = ( 2 ^ ( |s| / 2 ) ) ^ 2 by rw [ ← Real.rpow_natCast, ← Real.rpow_mul ( by positivity ) ] ; ring, show weight n |s| i = ( weight n ( |s| / 2 ) i ) ^ 2 by
                                                                                                                                        unfold weight; rw [ ← Real.rpow_natCast, ← Real.rpow_mul ( by exact add_nonneg zero_le_one <| Finset.sum_nonneg fun _ _ => sq_nonneg _ ) ] ; ring; ] ; ring;
          rw [ Real.sqrt_mul <| by positivity, Real.sqrt_mul <| by positivity, Real.sqrt_sq <| by positivity, Real.sqrt_sq <| by exact weight_nonneg _ _ ];
        convert mul_le_mul_of_nonneg_right h_peetre_step ( norm_nonneg ( b i * a ( m - i ) ) ) using 1
        all_goals (first | rfl | (norm_num; ring))
      by_cases h : Summable ( fun i => b i * a ( m - i ) ) <;> simp_all +decide [ tsum_eq_zero_of_not_summable, mul_assoc ];
      · refine' le_trans ( mul_le_mul_of_nonneg_left ( norm_tsum_le_tsum_norm _ ) ( Real.sqrt_nonneg _ ) ) _;
        · exact h.norm;
        · rw [ ← tsum_mul_left ];
          rw [ ← tsum_mul_left ];
          refine' Summable.tsum_le_tsum _ _ _;
          · aesop;
          · exact Summable.mul_left _ ( by simpa using h.norm );
          · refine' Summable.mul_left _ _;
            have h_summable : Summable (fun i => ‖b i‖ * (weight n (|s| / 2) i) * Real.sqrt (weight n s (m - i)) * ‖a (m - i)‖) := by
              have h_sqrt : ∀ i, Real.sqrt (weight n s (m - i)) * ‖a (m - i)‖ ≤ Real.sqrt (sobolevNormSq n s a) := by
                intro i
                have h_sqrt : weight n s (m - i) * ‖a (m - i)‖ ^ 2 ≤ sobolevNormSq n s a := by
                  exact Summable.le_tsum ( ha ) ( m - i ) ( fun _ _ => mul_nonneg ( weight_nonneg _ _ ) ( sq_nonneg _ ) );
                exact Real.le_sqrt_of_sq_le ( by nlinarith [ Real.mul_self_sqrt ( show 0 ≤ weight n s ( m - i ) by exact weight_nonneg _ _ ) ] )
              have h_summable : Summable (fun i => ‖b i‖ * (weight n (|s| / 2) i) * Real.sqrt (sobolevNormSq n s a)) := by
                exact hb.mul_right _;
              exact Summable.of_nonneg_of_le ( fun i => mul_nonneg ( mul_nonneg ( mul_nonneg ( norm_nonneg _ ) ( weight_nonneg _ _ ) ) ( Real.sqrt_nonneg _ ) ) ( norm_nonneg _ ) ) ( fun i => by nlinarith [ h_sqrt i, show 0 ≤ ‖b i‖ * weight n ( |s| / 2 ) i by exact mul_nonneg ( norm_nonneg _ ) ( weight_nonneg _ _ ) ] ) h_summable;
            simpa only [ mul_assoc ] using h_summable;
      · exact mul_nonneg ( Real.rpow_nonneg zero_le_two _ ) ( tsum_nonneg fun _ => mul_nonneg ( norm_nonneg _ ) ( mul_nonneg ( weight_nonneg _ _ ) ( mul_nonneg ( Real.sqrt_nonneg _ ) ( norm_nonneg _ ) ) ) );
    convert pow_le_pow_left₀ ( by positivity ) h_peetre_step 2 using 1
    all_goals (first
      | rfl
      | (rw [ mul_pow, Real.sq_sqrt <| weight_nonneg _ _ ])
      | ring)
  have h_young : Summable (fun m => (∑' i, ‖b i‖ * (weight n (|s| / 2) i) * Real.sqrt (weight n s (m - i)) * ‖a (m - i)‖) ^ 2) ∧
    ∑' m, (∑' i, ‖b i‖ * (weight n (|s| / 2) i) * Real.sqrt (weight n s (m - i)) * ‖a (m - i)‖) ^ 2 ≤
    (∑' i, ‖b i‖ * (weight n (|s| / 2) i)) ^ 2 * ∑' m, (weight n s m) * ‖a m‖ ^ 2 := by
      have := @young_conv_sq_bound n ( fun i => ‖b i‖ * weight n ( |s| / 2 ) i ) ( fun m => Real.sqrt ( weight n s m ) * ‖a m‖ ) ?_ ?_ ?_ ?_;
      · simp_all +decide [ mul_assoc, mul_pow, Real.sq_sqrt ( weight_nonneg _ _ ) ];
      · exact fun m => mul_nonneg ( norm_nonneg _ ) ( weight_nonneg _ _ );
      · exact fun m => mul_nonneg ( Real.sqrt_nonneg _ ) ( norm_nonneg _ );
      · exact hb;
      · simp_all +decide [ mul_pow, Real.sq_sqrt ( weight_nonneg _ _ ) ];
        exact ha;
  have h_summable : Summable (fun m => (weight n s m) * ‖∑' i, b i * a (m - i)‖ ^ 2) := by
    exact Summable.of_nonneg_of_le ( fun m => mul_nonneg ( weight_nonneg _ _ ) ( sq_nonneg _ ) ) h_peetre ( h_young.1.mul_left _ );
  have h_sqrt : Real.sqrt (∑' m, (weight n s m) * ‖∑' i, b i * a (m - i)‖ ^ 2) ≤ Real.sqrt ((2 ^ (|s| / 2 : ℝ)) ^ 2 * (∑' i, ‖b i‖ * (weight n (|s| / 2) i)) ^ 2 * ∑' m, (weight n s m) * ‖a m‖ ^ 2) := by
    refine Real.sqrt_le_sqrt ?_;
    refine' le_trans ( Summable.tsum_le_tsum h_peetre h_summable _ ) _;
    · exact Summable.mul_left _ h_young.1;
    · rw [ tsum_mul_left ] ; nlinarith [ show 0 ≤ ( 2 ^ ( |s| / 2 ) : ℝ ) ^ 2 by positivity ] ;
  refine ⟨h_summable, h_sqrt.trans_eq ?_⟩
  unfold sobolevNormSq
  rw [Real.sqrt_mul (by positivity), Real.sqrt_mul (by positivity), Real.sqrt_sq (by positivity), Real.sqrt_sq (tsum_nonneg fun _ => mul_nonneg (norm_nonneg _) (weight_nonneg _ _))]

:= by
  unfold weight;
  rw [ Real.rpow_add ( by exact add_pos_of_pos_of_nonneg zero_lt_one ( Finset.sum_nonneg fun _ _ => sq_nonneg _ ) ) ]

statement:
lemma sobolevNormSq_mono {s t : ℝ} {a : (Fin n → ℤ) → ℂ}
    (ha : MemSobolev n t a) (hst : s ≤ t) :
    sobolevNormSq n s a ≤ sobolevNormSq n t a

proof:
:= by
  unfold fourierExp;
  convert Complex.exp_periodic.int_mul ( m j ) _ using 2 ; ring;
  rw [ Finset.sum_eq_add_sum_sdiff_singleton_of_mem ( Finset.mem_univ j ) ] ; ring;
  rw [ Finset.sum_congr rfl fun x hx => by aesop ] ; norm_num ; ring

:= by
  rw [ hasDerivAt_iff_tendsto_slope_zero ];

  have h_deriv_sum : Filter.Tendsto (fun t : ℝ => ∑' m : Fin n → ℤ, (b m * (fourierExp n m (Function.update θ j (θ j + t)) - fourierExp n m (Function.update θ j (θ j)))) / t) (nhdsWithin 0 {0}ᶜ) (nhds (∑' m : Fin n → ℤ, partialCoeff j b m * fourierExp n m θ)) := by
    refine' ( tendsto_tsum_of_dominated_convergence _ _ _ );
    use fun m => ‖partialCoeff j b m‖;
    · exact hbj;
    · intro m;
      have h_deriv : HasDerivAt (fun t : ℝ => fourierExp n m (Function.update θ j t)) (Complex.I * (m j : ℂ) * fourierExp n m θ) (θ j) := by
        unfold fourierExp;
        simp +decide [ Function.update_apply, Finset.sum_ite, Finset.filter_eq', Finset.filter_ne' ];
        convert HasDerivAt.comp ( θ j ) ( Complex.hasDerivAt_exp _ ) ( HasDerivAt.const_mul Complex.I <| HasDerivAt.add ( HasDerivAt.const_mul ( m j : ℂ ) <| hasDerivAt_id _ |> HasDerivAt.ofReal_comp ) <| hasDerivAt_const _ ((∑ x, ((m x : ℂ) * (θ x : ℂ))) - (m j : ℂ) * (θ j : ℂ)) ) using 1
        all_goals (first
          | rfl
          | (simp only [Pi.add_apply, id_eq]; push_cast; ring))
      convert h_deriv.tendsto_slope_zero.const_mul ( b m ) using 2 <;> norm_num [ div_eq_mul_inv, mul_assoc, mul_comm, mul_left_comm, partialCoeff ];
    · 
      have h_exp_diff : ∀ x y : ℝ, ‖Complex.exp (Complex.I * x) - Complex.exp (Complex.I * y)‖ ≤ |x - y| := by

        have h_exp_diff : ∀ x y : ℝ, ‖Complex.exp (Complex.I * x) - Complex.exp (Complex.I * y)‖ = 2 * |Real.sin ((x - y) / 2)| := by
          norm_num [ Complex.norm_def, Complex.normSq, Complex.exp_re, Complex.exp_im ];
          intro x y; rw [ Real.sqrt_eq_iff_mul_self_eq ] <;> norm_num <;> ring <;> norm_num [ Real.sin_sq, Real.cos_sq ] <;> ring;
          · rw [ Real.cos_sub ] ; ring;
          · nlinarith [ sq_nonneg ( Real.cos x - Real.cos y ), sq_nonneg ( Real.sin x - Real.sin y ), Real.cos_sq' x, Real.cos_sq' y ];

        have h_sin_bound : ∀ z : ℝ, |Real.sin z| ≤ |z| := by
          exact fun z => Real.abs_sin_le_abs;
        grind +revert;
      filter_upwards [ self_mem_nhdsWithin ] with t ht k ; simp_all +decide [ fourierExp, partialCoeff ];
      rw [ div_le_iff₀ ( abs_pos.mpr ht ) ];
      convert mul_le_mul_of_nonneg_left ( h_exp_diff ( ∑ x : Fin n, ( k x : ℝ ) * ( Function.update θ j ( θ j + t ) x ) ) ( ∑ x : Fin n, ( k x : ℝ ) * ( θ x ) ) ) ( norm_nonneg ( b k ) ) using 1 ; norm_num [ Finset.sum_update_of_mem ] ; ring;
      simp +decide [ Finset.sum_update_of_mem, Function.update_apply ] ; ring;
      simp +decide [ Finset.sum_ite, Finset.filter_eq', Finset.filter_ne' ] ; ring;
      norm_num [ mul_assoc, mul_comm, mul_left_comm, abs_mul ];
  convert h_deriv_sum using 2;
  rw [ ← Summable.tsum_sub ];
  · simp +decide [ div_eq_inv_mul, mul_sub, mul_assoc, mul_comm, mul_left_comm, ← tsum_mul_left ];
  · exact Summable.of_norm <| by simpa [ norm_fourierExp ] using hb;
  · exact .of_norm <| by simpa [ norm_fourierExp ] using hb;

:= by
  unfold fourierExp;
  norm_num [ Complex.ext_iff, Complex.exp_re, Complex.exp_im ]

:= by
  split_ifs with h;
  · simp +decide [ ← h, fourierExp, Complex.exp_ne_zero ];
    norm_num [ Complex.mul_conj, Complex.normSq_eq_norm_sq, Complex.norm_exp ];
    erw [ MeasureTheory.measureReal_def ];
    erw [ Real.volume_Icc_pi ] ; norm_num [ mul_comm ];
    rw [ ENNReal.toReal_ofReal ( by positivity ) ] ; norm_num;
  · 
    obtain ⟨j, hj⟩ : ∃ j : Fin n, m j ≠ m₀ j := by
      exact Function.ne_iff.mp h;

    have h_prod : ∫ θ : Fin n → ℝ in Set.Icc (0 : Fin n → ℝ) (2 * Real.pi • 1), Complex.exp (Complex.I * ∑ i : Fin n, ((m i - m₀ i) : ℂ) * θ i) = ∏ i : Fin n, ∫ θ : ℝ in Set.Icc 0 (2 * Real.pi), Complex.exp (Complex.I * ((m i - m₀ i) : ℂ) * θ) := by
      have h_prod : ∫ θ : Fin n → ℝ in Set.Icc (0 : Fin n → ℝ) (2 * Real.pi • 1), Complex.exp (Complex.I * ∑ i : Fin n, ((m i - m₀ i) : ℂ) * θ i) = ∫ θ : Fin n → ℝ, (∏ i : Fin n, (if 0 ≤ θ i ∧ θ i ≤ 2 * Real.pi then Complex.exp (Complex.I * ((m i - m₀ i) : ℂ) * θ i) else 0)) := by
        rw [ ← MeasureTheory.integral_indicator ] <;> norm_num [ Set.indicator, Pi.le_def, forall_and ];
        congr with x ; split_ifs <;> simp_all +decide [ mul_assoc, mul_comm, mul_left_comm, Finset.prod_ite ];
        · rw [ ← Complex.exp_sum, Finset.mul_sum _ _ _ ];
        · grind;
      have h_prod : ∀ (f : Fin n → ℝ → ℂ), (∫ θ : Fin n → ℝ, ∏ i : Fin n, f i (θ i)) = ∏ i : Fin n, ∫ θ : ℝ, f i θ := by
        exact fun f => MeasureTheory.integral_fin_nat_prod_volume_eq_prod f;
      convert h_prod ( fun i θ => if 0 ≤ θ ∧ θ ≤ 2 * Real.pi then Complex.exp ( Complex.I * ( m i - m₀ i ) * θ ) else 0 ) using 1;
      exact Finset.prod_congr rfl fun _ _ => by rw [ ← MeasureTheory.integral_indicator ] <;> norm_num [ Set.indicator ] ;

    have h_integral_zero : ∀ j : Fin n, m j ≠ m₀ j → ∫ θ : ℝ in Set.Icc 0 (2 * Real.pi), Complex.exp (Complex.I * ((m j - m₀ j) : ℂ) * θ) = 0 := by
      intro j hj; rw [ MeasureTheory.integral_Icc_eq_integral_Ioc, ← intervalIntegral.integral_of_le Real.two_pi_pos.le ] ;
      have := @integral_exp_mul_complex 0 ( 2 * Real.pi );
      convert this ( show ( I * ( m j - m₀ j : ℂ ) ) ≠ 0 from mul_ne_zero Complex.I_ne_zero <| sub_ne_zero_of_ne <| mod_cast hj ) using 1 ; norm_num;
      exact Eq.symm ( div_eq_zero_iff.mpr <| Or.inl <| sub_eq_zero.mpr <| Complex.exp_eq_one_iff.mpr ⟨ m j - m₀ j, by push_cast; ring ⟩ );
    convert h_prod using 1;
    · unfold fourierExp; norm_num [ Complex.exp_add, Complex.exp_neg, mul_sub, sub_mul, Finset.sum_sub_distrib ] ;
      norm_num [ Complex.exp_sub, Complex.exp_neg, Complex.exp_conj ];
      norm_num [ div_eq_mul_inv, Complex.inv_def, Complex.normSq_eq_norm_sq, Complex.norm_exp ];
    · rw [ Finset.prod_eq_zero ( Finset.mem_univ j ) ( h_integral_zero j hj ) ] ; norm_num

:= by

  have h_expand : ∫ θ in Set.Icc (0 : Fin n → ℝ) (2 * Real.pi • (1 : Fin n → ℝ)), fourierSynthesis n a θ * (starRingEnd ℂ) (fourierExp n m₀ θ) = ∑' m : Fin n → ℤ, a m * ∫ θ in Set.Icc (0 : Fin n → ℝ) (2 * Real.pi • (1 : Fin n → ℝ)), fourierExp n m θ * (starRingEnd ℂ) (fourierExp n m₀ θ) := by
    simp +decide only [fourierSynthesis, ← MeasureTheory.integral_const_mul];
    rw [ ← MeasureTheory.integral_tsum ];
    · simp +decide only [← tsum_mul_right, ← mul_assoc];
    · intro m; apply_rules [ Continuous.aestronglyMeasurable, Continuous.mul, continuous_const ];
      · exact Complex.continuous_exp.comp <| Continuous.mul continuous_const <| by continuity;
      · exact Complex.continuous_conj.comp ( Complex.continuous_exp.comp <| by continuity );
    · refine' ne_of_lt ( lt_of_le_of_lt ( ENNReal.tsum_le_tsum fun m => _ ) _ );
      use fun m => ENNReal.ofReal ( ‖a m‖ * ( 2 * Real.pi ) ^ n );
      · refine' le_trans ( MeasureTheory.lintegral_mono fun x => _ ) _;
        use fun x => ENNReal.ofReal ( ‖a m‖ );
        · rw [ ENNReal.le_ofReal_iff_toReal_le ] <;> norm_num [ norm_fourierExp ];
          finiteness;
        · simp +decide [ Real.volume_Icc_pi, mul_pow ];
          rw [ ENNReal.ofReal_mul ( by positivity ), ENNReal.ofReal_pow ( by positivity ) ] ; ring_nf ; norm_num;
      · rw [ ← ENNReal.ofReal_tsum_of_nonneg ] <;> norm_num;
        · exact fun m => mul_nonneg ( norm_nonneg _ ) ( pow_nonneg ( by positivity ) _ );
        · exact ha.mul_right _;
  rw [ h_expand, tsum_eq_single m₀ ];
  · rw [ mul_comm, fourierExp_inner_eq ] ; norm_num;
  · intro m hm; rw [ fourierExp_inner_eq m m₀ ] ; aesop;

:= by
  convert congr_arg ( fun x : ℂ => ( ( 2 * Real.pi ) ^ n : ℂ ) ⁻¹ * x ) ( fourierSynthesis_inner ha m ) using 1;
  · simp +decide [ stdFourierCoeff, starRingEnd_fourierExp ];
  · norm_num [ ← mul_assoc, Real.pi_ne_zero ]

statement:
lemma sobolevNormSqDistrib_mono {s t : ℝ} {φ : TrigPolyDual n}
    (hφ : MemSobolevDistrib n t φ) (hst : s ≤ t) :
    sobolevNormSqDistrib n s φ ≤ sobolevNormSqDistrib n t φ

proof:
:= by
  obtain ⟨ ψ, hψ ⟩ := compactInclusion_lp_weighted hst ( fun k => fourierCoeffDistrib ( φseq k ) ) ( fun k => hmem k ) ( fun k => hbdd k );
  obtain ⟨ b, hb₁, hb₂ ⟩ := hψ.2;
  refine' ⟨ ψ, hψ.1, seqToDual n b, _, _ ⟩;
  · convert hb₁ using 1;
    unfold MemSobolevDistrib;
    rw [ fourierCoeffDistrib_seqToDual ];
  · 
    have h_fourierCoeffDistrib : ∀ k, fourierCoeffDistrib (φseq (ψ k) - seqToDual n b) = fun m => fourierCoeffDistrib (φseq (ψ k)) m - b m := by
      intro k; ext m; simp +decide [ fourierCoeffDistrib, seqToDual ] ;
    unfold sobolevNormSqDistrib; aesop;

:= by
  convert seqToDual_fourierCoeffDistrib φ using 1;
  refine' LinearMap.ext fun x => _;
  convert congr_arg ( fun a => ( Finsupp.linearCombination ℂ ( fun m => a ( -m ) ) ) x ) ( funext fun m => sobolev_embedding_factorization hn hs hφ m ) using 1
  all_goals rfl

:= by
  unfold periodicExtension; intro x k; symm; simp +decide [ IsPeriodic2Pi, periodicShift ] ;
  rw [ ← Equiv.tsum_eq ( Equiv.addLeft k ) ] ; simp +decide [ periodicShift ] ; ring;
  unfold periodicShift; congr; ext; simp +decide [ add_assoc ] ;
  exact congr_arg _ ( by ext; simp +decide [ mul_add ] )

statement:
lemma periodicExtension_contDiff {φ : (Fin n → ℝ) → ℂ}
    (hsmooth : ContDiff ℝ ∞ φ) (hsupp : HasCompactSupport φ) :
    ContDiff ℝ ∞ (periodicExtension n φ)

proof:
:= by
  have h_compact_support : ∃ R : ℝ, ∀ x : Fin n → ℝ, ‖x‖ ≥ R → φ x = 0 := by
    obtain ⟨ R, hR ⟩ := hsupp.exists_pos_le_norm;
    exact ⟨ R, hR.2 ⟩;

  have h_locally_finite : ∀ x : Fin n → ℝ, ∃ U : Set (Fin n → ℝ), IsOpen U ∧ x ∈ U ∧ Set.Finite {k : Fin n → ℤ | ∃ y ∈ U, φ (y + periodicShift n k) ≠ 0} := by
    intro x
    obtain ⟨R, hR⟩ : ∃ R : ℝ, ∀ x : Fin n → ℝ, ‖x‖ ≥ R → φ x = 0 := h_compact_support
    use Metric.ball x 1;
    refine' ⟨ Metric.isOpen_ball, Metric.mem_ball_self zero_lt_one, _ ⟩;

    have h_bound : ∀ k : Fin n → ℤ, (∃ y ∈ Metric.ball x 1, φ (y + periodicShift n k) ≠ 0) → ∀ i : Fin n, |(k i : ℝ)| ≤ (R + ‖x‖ + 1) / (2 * Real.pi) := by
      intros k hk i
      obtain ⟨y, hy_ball, hy_nonzero⟩ := hk
      have h_bound : ‖y + periodicShift n k‖ < R := by
        exact lt_of_not_ge fun h => hy_nonzero <| hR _ h;
      have h_bound : |(y i + 2 * Real.pi * (k i : ℝ))| ≤ R := by
        exact le_trans ( by simpa [Pi.add_apply, periodicShift] using norm_le_pi_norm ( y + periodicShift n k ) i ) h_bound.le;
      have h_bound : |y i| ≤ ‖x‖ + 1 := by
        have h_bound : |y i - x i| ≤ ‖y - x‖ := by
          exact norm_le_pi_norm ( y - x ) i;
        exact abs_le.mpr ⟨ by linarith [ abs_le.mp h_bound, abs_le.mp ( norm_le_pi_norm x i ), abs_le.mp ( norm_le_pi_norm ( y - x ) i ), show ‖y - x‖ < 1 from by rw [← dist_eq_norm]; exact hy_ball ], by linarith [ abs_le.mp h_bound, abs_le.mp ( norm_le_pi_norm x i ), abs_le.mp ( norm_le_pi_norm ( y - x ) i ), show ‖y - x‖ < 1 from by rw [← dist_eq_norm]; exact hy_ball ] ⟩;
      rw [ le_div_iff₀ ] <;> cases abs_cases ( k i : ℝ ) <;> cases abs_cases ( y i + 2 * Real.pi * ( k i : ℝ ) ) <;> cases abs_cases ( y i ) <;> nlinarith [ Real.pi_gt_three ];

    have h_finite_k : Set.Finite {k : Fin n → ℤ | ∀ i : Fin n, |(k i : ℝ)| ≤ (R + ‖x‖ + 1) / (2 * Real.pi)} := by
      have h_finite_k : ∀ i : Fin n, Set.Finite {k : ℤ | |(k : ℝ)| ≤ (R + ‖x‖ + 1) / (2 * Real.pi)} := by
        exact fun i => Set.Finite.subset ( Set.finite_Icc ( -⌈ ( R + ‖x‖ + 1 ) / ( 2 * Real.pi ) ⌉ ) ⌈ ( R + ‖x‖ + 1 ) / ( 2 * Real.pi ) ⌉ ) fun k hk => ⟨ neg_le_of_abs_le <| by exact_mod_cast hk.out.trans <| Int.le_ceil _, le_of_abs_le <| by exact_mod_cast hk.out.trans <| Int.le_ceil _ ⟩;
      exact Set.Finite.subset ( Set.Finite.pi fun i => h_finite_k i ) fun k hk => by simpa using hk;
    exact h_finite_k.subset fun k hk => h_bound k hk;
  have h_locally_finite_sum : ∀ x : Fin n → ℝ, ∃ U : Set (Fin n → ℝ), IsOpen U ∧ x ∈ U ∧ ∃ S : Finset (Fin n → ℤ), ∀ y ∈ U, ∑' k : Fin n → ℤ, φ (y + periodicShift n k) = ∑ k ∈ S, φ (y + periodicShift n k) := by
    intro x
    obtain ⟨U, hU_open, hxU, hU_finite⟩ := h_locally_finite x
    use U, hU_open, hxU
    use hU_finite.toFinset
    intro y hy
    have h_sum_eq : ∑' k : Fin n → ℤ, φ (y + periodicShift n k) = ∑ k ∈ hU_finite.toFinset, φ (y + periodicShift n k) := by
      rw [ tsum_eq_sum ];
      simp +contextual [ hU_finite.mem_toFinset ];
      exact fun k hk => hk y hy
    exact h_sum_eq;
  refine' contDiff_iff_contDiffAt.mpr _;
  intro x
  obtain ⟨U, hU_open, hxU, S, hS⟩ := h_locally_finite_sum x
  have h_cont_diff : ContDiffOn ℝ ∞ (fun y => ∑ k ∈ S, φ (y + periodicShift n k)) U := by
    exact ContDiffOn.sum fun k hk => hsmooth.comp_contDiffOn ( contDiffOn_id.add contDiffOn_const );
