theorem stdFourierCoeff_partialDeriv (hn : 0 < n) {g : (Fin n → ℝ) → ℂ}
    (hg : ContDiff ℝ ∞ g) (hper : IsPeriodic2Pi g) (j : Fin n) (m : Fin n → ℤ) :
    stdFourierCoeff n (partialDeriv j g) m = Complex.I * (m j : ℂ) * stdFourierCoeff n g m

lemma norm_stdFourierCoeff_le {g : (Fin n → ℝ) → ℂ} {M : ℝ}
    (hM : ∀ θ ∈ Set.Icc (0 : Fin n → ℝ) (2 * π • (1 : Fin n → ℝ)), ‖g θ‖ ≤ M)
    (m : Fin n → ℤ) : ‖stdFourierCoeff n g m‖ ≤ M

lemma memSobolev_of_rapid_decay (hn : 0 < n) {a : (Fin n → ℤ) → ℂ}
    (h : ∀ N : ℕ, ∃ C : ℝ, 0 < C ∧ ∀ m, ‖a m‖ ≤ C * weight n (-(N / 2 : ℝ)) m)
    (s : ℝ) : MemSobolev n s a

lemma summable_stdFourierCoeff_of_smoothPeriodic (hn : 0 < n) {f : (Fin n → ℝ) → ℂ}
    (hsmooth : ContDiff ℝ ∞ f) (hper : IsPeriodic2Pi f) :
    Summable (stdFourierCoeff n f)

theorem isRapidDecay_stdFourierCoeff (hn : 0 < n) {f : (Fin n → ℝ) → ℂ}
    (hsmooth : ContDiff ℝ ∞ f) (hper : IsPeriodic2Pi f) :
    IsRapidDecay n (stdFourierCoeff n f)

lemma stdFourierCoeff_finset_sum' {ι : Type*} (S : Finset ι) {f : ι → (Fin n → ℝ) → ℂ}
    (hf : ∀ i ∈ S, Continuous (f i)) :
    stdFourierCoeff n (fun x => ∑ i ∈ S, f i x) = fun m => ∑ i ∈ S, stdFourierCoeff n (f i) m

theorem stdFourierCoeff_mul (hn : 0 < n) {f g : (Fin n → ℝ) → ℂ}
    (hf : ContDiff ℝ ∞ f) (hfp : IsPeriodic2Pi f) (hg : ContDiff ℝ ∞ g) (hgp : IsPeriodic2Pi g) :
    stdFourierCoeff n (fun x => f x * g x) = seqConv (stdFourierCoeff n f) (stdFourierCoeff n g)

theorem stdFourierCoeff_partialDeriv' (hn : 0 < n) {f : (Fin n → ℝ) → ℂ}
    (hf : ContDiff ℝ ∞ f) (hper : IsPeriodic2Pi f) (j : Fin n) :
    stdFourierCoeff n (partialDeriv j f) = partialCoeff j (stdFourierCoeff n f)

theorem eq_of_stdFourierCoeff_eq (hn : 0 < n) {f g : (Fin n → ℝ) → ℂ}
    (hf : ContDiff ℝ ∞ f) (hfp : IsPeriodic2Pi f) (hg : ContDiff ℝ ∞ g) (hgp : IsPeriodic2Pi g)
    (h : stdFourierCoeff n f = stdFourierCoeff n g) : f = g

lemma fourierSynthesis_add' {a b : (Fin n → ℤ) → ℂ}
    (ha : Summable (fun m => ‖a m‖)) (hb : Summable (fun m => ‖b m‖)) :
    fourierSynthesis n (fun m => a m + b m) = fun θ => fourierSynthesis n a θ + fourierSynthesis n b θ

lemma fourierSynthesis_sub {a b : (Fin n → ℤ) → ℂ}
    (ha : Summable (fun m => ‖a m‖)) (hb : Summable (fun m => ‖b m‖)) :
    fourierSynthesis n (fun m => a m - b m) = fun θ => fourierSynthesis n a θ - fourierSynthesis n b θ

