    (ha : MemSobolev n s a) (m : Fin n → ℤ) :
    weight n s m * ‖a m‖ ^ 2 ≤ sobolevNormSq n s a

lemma MemSobolev.add {s : ℝ} {a b : (Fin n → ℤ) → ℂ}
    (ha : MemSobolev n s a) (hb : MemSobolev n s b) :
    MemSobolev n s (fun m => a m + b m)

lemma MemSobolev.sub {s : ℝ} {a b : (Fin n → ℤ) → ℂ}
    (ha : MemSobolev n s a) (hb : MemSobolev n s b) :
    MemSobolev n s (fun m => a m - b m)

lemma sobolevNormSq_add_le {s : ℝ} {a b : (Fin n → ℤ) → ℂ}
    (ha : MemSobolev n s a) (hb : MemSobolev n s b) :
    sobolevNormSq n s (fun m => a m + b m) ≤ 2 * sobolevNormSq n s a + 2 * sobolevNormSq n s b

lemma sobolevNormSq_sub_le {s : ℝ} {a b : (Fin n → ℤ) → ℂ}
    (ha : MemSobolev n s a) (hb : MemSobolev n s b) :
    sobolevNormSq n s (fun m => a m - b m) ≤ 2 * sobolevNormSq n s a + 2 * sobolevNormSq n s b

lemma MemSobolev.finset_sum {ι : Type*} {s : ℝ} (S : Finset ι) {a : ι → (Fin n → ℤ) → ℂ}
    (ha : ∀ i ∈ S, MemSobolev n s (a i)) :
    MemSobolev n s (fun m => ∑ i ∈ S, a i m)

lemma sobolevNormSq_finset_sum_le {ι : Type*} {s : ℝ} (S : Finset ι) {a : ι → (Fin n → ℤ) → ℂ}
    (ha : ∀ i ∈ S, MemSobolev n s (a i)) :
    sobolevNormSq n s (fun m => ∑ i ∈ S, a i m) ≤ S.card * ∑ i ∈ S, sobolevNormSq n s (a i)

lemma sobolevNormSq_laplacianCoeff_le {s : ℝ} {a : (Fin n → ℤ) → ℂ}
    (ha : MemSobolev n (s + 2) a) :
    sobolevNormSq n s (laplacianCoeff a) ≤ sobolevNormSq n (s + 2) a

private lemma iteratedDeriv_expI (k : ℕ) (t : ℝ) :
    iteratedDeriv k (fun t : ℝ => Complex.exp (Complex.I * (t : ℂ))) t
      = Complex.I ^ k * Complex.exp (Complex.I * (t : ℂ))

