    (ha : IsRapidDecay n a) (j : Fin n) :
    partialDeriv j (fourierSynthesis n a) = fourierSynthesis n (partialCoeff j a)

private lemma summable_norm_prod_shear {a b : (Fin n → ℤ) → ℂ}
    (ha : Summable (fun m => ‖a m‖)) (hb : Summable (fun m => ‖b m‖)) :
