lemma periodicShift_unique {x : Fin n → ℝ} {k k' : Fin n → ℤ}
    (hk : ∀ j : Fin n, |(x + NashEmbedding.Sobolev.periodicShift n k) j| < π)
    (hk' : ∀ j : Fin n, |(x + NashEmbedding.Sobolev.periodicShift n k') j| < π) : k = k'

lemma fderiv_cube_of_half {χ : (Fin n → ℝ) → ℝ}
    (hcube : ∀ x, χ x ≠ 0 → ∀ j : Fin n, |x j| < π / 2) (v : Fin n → ℝ) :
    ∀ x, fderiv ℝ χ x v ≠ 0 → ∀ j : Fin n, |x j| < π

lemma memSobolevDistrib_smul {s : ℝ} {u : NashEmbedding.Sobolev.TrigPolyDual n}
    (hu : MemSobolevDistrib n s u)
    (c : ℂ) : MemSobolevDistrib n s (c • u)

lemma memSobolevDistrib_finset_sum {ι : Type*} (t : Finset ι) {s : ℝ}
    {v : ι → NashEmbedding.Sobolev.TrigPolyDual n} (hv : ∀ a, MemSobolevDistrib n s (v a)) :
    MemSobolevDistrib n s (∑ a ∈ t, v a)

lemma det_contDiff {M : (Fin n → ℝ) → Matrix ι ι ℝ}
    (hM : ∀ i j, ContDiff ℝ ∞ (fun x => M x i j)) :
    ContDiff ℝ ∞ (fun x => (M x).det)

lemma adjugate_contDiff {M : (Fin n → ℝ) → Matrix ι ι ℝ}
    (hM : ∀ i j, ContDiff ℝ ∞ (fun x => M x i j)) (i j : ι) :
    ContDiff ℝ ∞ (fun x => (M x).adjugate i j)

lemma inv_contDiff {M : (Fin n → ℝ) → Matrix ι ι ℝ}
    (hM : ∀ i j, ContDiff ℝ ∞ (fun x => M x i j)) (hdet : ∀ x, (M x).det ≠ 0) (i j : ι) :
    ContDiff ℝ ∞ (fun x => (M x)⁻¹ i j)

lemma gramMatrix_contDiff {e : ι → (Fin n → ℝ) → (Fin N → ℝ)}
    (he : ∀ i, ContDiff ℝ ∞ (e i)) (i j : ι) :
    ContDiff ℝ ∞ (fun x => gramMatrix e x i j)

lemma gramMatrix_periodic {e : ι → (Fin n → ℝ) → (Fin N → ℝ)}
    (he : ∀ i, IsPeriodic2Pi (e i)) (x : Fin n → ℝ) (k : Fin n → ℤ) :
    gramMatrix e (x + periodicShift n k) = gramMatrix e x

theorem dualFrame_dotProduct {e : ι → (Fin n → ℝ) → (Fin N → ℝ)}
    (he : IsPointwiseLinIndep e) (i j : ι) (x : Fin n → ℝ) :
    dualFrame e i x ⬝ᵥ e j x = if i = j then 1 else 0

theorem dualFrame_contDiff {e : ι → (Fin n → ℝ) → (Fin N → ℝ)}
    (he : IsPointwiseLinIndep e) (hs : ∀ i, ContDiff ℝ ∞ (e i)) (i : ι) :
    ContDiff ℝ ∞ (dualFrame e i)

theorem dualFrame_smoothPeriodic {e : ι → (Fin n → ℝ) → (Fin N → ℝ)}
    (he : IsPointwiseLinIndep e) (hsp : ∀ i, SmoothPeriodic (e i)) (i : ι) :
    SmoothPeriodic (dualFrame e i)

lemma vecNormSq_mul_le_top {r k : ℕ} (hk : r ≤ k) {v w : VecSeq n N}
    (hv : VMem n N k v) (hw : VMem n N k w) :
    vecNormSq n N r v * vecNormSq n N r w ≤ top n N r k v w

lemma lower_mono {r k : ℕ} (hk : r ≤ k) {v w : VecSeq n N}
    (hv : VMem n N (k + 1 : ℕ) v) (hw : VMem n N (k + 1 : ℕ) w) :
    lower n N r k v w ≤ lower n N r (k + 1) v w

lemma ScalarTame.add {r : ℕ} {Q₁ Q₂ : VecSeq n N → VecSeq n N → Seq n} {A₁ A₂ : ℝ} {B₁ B₂ : ℕ → ℝ}
    (h₁ : ScalarTame n N r Q₁ A₁ B₁) (h₂ : ScalarTame n N r Q₂ A₂ B₂) :
    ScalarTame n N r (fun v w m => Q₁ v w m + Q₂ v w m) (2 * (A₁ + A₂)) (fun k => 2 * (B₁ k + B₂ k))

lemma ScalarTame.const_mul {r : ℕ} {Q : VecSeq n N → VecSeq n N → Seq n} {A' : ℝ} {Bk : ℕ → ℝ}
    (h : ScalarTame n N r Q A' Bk) (c : ℝ) :
    ScalarTame n N r (fun v w m => (c : ℂ) * Q v w m) (c ^ 2 * A') (fun k => c ^ 2 * Bk k)

lemma VecTame.add {r : ℕ} {Q₁ Q₂ : VecSeq n N → VecSeq n N → VecSeq n N} {A₁ A₂ : ℝ} {B₁ B₂ : ℕ → ℝ}
    (h₁ : VecTame n N r Q₁ A₁ B₁) (h₂ : VecTame n N r Q₂ A₂ B₂) :
    VecTame n N r (fun v w => Q₁ v w + Q₂ v w) (2 * (A₁ + A₂)) (fun k => 2 * (B₁ k + B₂ k))

lemma contDiff_dotProduct {N : ℕ} {u v : (Fin n → ℝ) → (Fin N → ℝ)}
    (hu : ContDiff ℝ ∞ u) (hv : ContDiff ℝ ∞ v) :
    ContDiff ℝ ∞ (fun y => u y ⬝ᵥ v y)

lemma pderiv_dotProduct {N : ℕ} {u v : (Fin n → ℝ) → (Fin N → ℝ)}
    (hu : ContDiff ℝ ∞ u) (hv : ContDiff ℝ ∞ v) (i : Fin n) (x : Fin n → ℝ) :
    pderiv i (fun y => u y ⬝ᵥ v y) x = pderiv i u x ⬝ᵥ v x + u x ⬝ᵥ pderiv i v x

lemma SmoothPeriodic.dotProduct {u w : (Fin n → ℝ) → (Fin N → ℝ)}
    (hu : SmoothPeriodic u) (hw : SmoothPeriodic w) :
    SmoothPeriodic (fun x => u x ⬝ᵥ w x)

lemma stdFourierCoeff_dotProduct (hn : 0 < n) {u w : (Fin n → ℝ) → (Fin N → ℝ)}
    (hu : SmoothPeriodic u) (hw : SmoothPeriodic w) :
    stdFourierCoeff n (fun x => ((u x ⬝ᵥ w x : ℝ) : ℂ)) = dotConv (vcoeff n u) (vcoeff n w)

lemma vecNormSq_finset_sum_le {ι : Type*} {s : ℝ} (S : Finset ι) {v : ι → VecSeq n N}
    (hv : ∀ i ∈ S, VMem n N s (v i)) :
    vecNormSq n N s (∑ i ∈ S, v i) ≤ S.card * ∑ i ∈ S, vecNormSq n N s (v i)

lemma vecNormSq_smulSeq_le (hn : 0 < n) {s : ℝ} (hs : (n : ℝ) < 2 * s) {f : Seq n}
    (hf : MemSobolev n s f) {a : VecSeq n N} (ha : VMem n N s a) :
    vecNormSq n N s (smulSeq f a) ≤ mt2Const n s * sobolevNormSq n s f * vecNormSq n N s a

private lemma stdFourierCoeff_ssynth (hn : 0 < n) {f : Seq n} (hf : IsRapidDecay n f)
    (hfix : conjReflect f = f) :
    stdFourierCoeff n (fun x => ((ssynth n f x : ℝ) : ℂ)) = f
